    Bug 1982203 follow-up - Empty trash in browser_accountHubBackground.js to avoid breaking a later test. rs=bustage-fix DONTBUILD
    If browser_accountHubBackground.js and browser_accountTelemetry.js are run together, the latter
    reports an error due to the messages left over from the former. Coincidentally,
    browser_accountHubOpen.js empties the trash, hiding the problem, but not on macOS.

diff --git a/mail/test/browser/account/browser_accountHubBackground.js b/mail/test/browser/account/browser_accountHubBackground.js
index 7337a9b0905..ecf62290e21 100644
--- a/mail/test/browser/account/browser_accountHubBackground.js
+++ b/mail/test/browser/account/browser_accountHubBackground.js
@@ -55,6 +55,7 @@ add_setup(async function () {
     about3Pane.messagePane.clearAll();
     MailServices.junk.resetTrainingData();
     testFolder.deleteSelf(null);
+    rootFolder.getFolderWithFlags(Ci.nsMsgFolderFlags.Trash).emptyTrash(null);
   });
 });
